using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, (string Category, decimal Price)> _products = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category -> set of product codes
    private readonly Dictionary<string, HashSet<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        // Remove from old category index if re-adding
        if (_products.TryGetValue(code, out var existing) &&
            !existing.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
        {
            if (_categoryIndex.TryGetValue(existing.Category, out var oldSet))
            {
                oldSet.Remove(code);
                if (oldSet.Count == 0)
                    _categoryIndex.Remove(existing.Category);
            }
        }

        _products[code] = (category, price);

        ref var set = ref CollectionsMarshal.GetValueRefOrAddDefault(_categoryIndex, category, out bool exists);
        set ??= new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        set.Add(code);
    }

    public string? GetCategory(string code)
        => _products.TryGetValue(code, out var product) ? product.Category : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_products.TryGetValue(code, out var product))
                total += product.Price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_categoryIndex.TryGetValue(category, out var set))
            return new List<string>(set);

        return [];
    }
}

